package database

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
)

// MonetizationLink is one tracked redirect for a suggestion. The code is
// generated by the caller. The destination is the offer URL.
type MonetizationLink struct {
	Code        string
	OfferID     string
	Destination string
}

// MonetizationSuggestion is the row stored for one suggest call.
// DraftSHA256 is the hash of the stripped text. Keywords are the tokens
// that overlapped a returned offer. The draft is not a field.
type MonetizationSuggestion struct {
	OwnerID     string
	DraftSHA256 string
	Keywords    []string
	Surface     string
	Lang        string
	OfferIDs    []string
	Mode        string
	Links       []MonetizationLink
}

// SaveMonetizationSuggestion inserts the hash row and its tracked links.
// It does not insert a placement.
func (d *DB) SaveMonetizationSuggestion(ctx context.Context, in MonetizationSuggestion) (string, error) {
	if in.Keywords == nil {
		in.Keywords = []string{}
	}
	if in.OfferIDs == nil {
		in.OfferIDs = []string{}
	}
	tx, err := d.Pool.Begin(ctx)
	if err != nil {
		return "", err
	}
	defer tx.Rollback(ctx)
	var id string
	err = tx.QueryRow(ctx, `
INSERT INTO monetization_suggestions(owner_id, draft_sha256, keywords, surface, lang, offer_ids, mode)
VALUES($1::uuid, $2, $3, $4, $5, $6, $7)
RETURNING id::text`, in.OwnerID, in.DraftSHA256, in.Keywords, in.Surface, in.Lang, in.OfferIDs, in.Mode).Scan(&id)
	if err != nil {
		return "", err
	}
	for _, link := range in.Links {
		if _, err = tx.Exec(ctx, `
INSERT INTO monetization_suggestion_links(code, suggestion_id, offer_id, destination)
VALUES($1, $2::uuid, $3, $4)`, link.Code, id, link.OfferID, link.Destination); err != nil {
			return "", err
		}
	}
	if err = tx.Commit(ctx); err != nil {
		return "", err
	}
	return id, nil
}

// FollowMonetizationLink returns the https destination for a suggestion code.
// count increments the click total. A missing code is pgx.ErrNoRows.
// The draft is not read.
func (d *DB) FollowMonetizationLink(ctx context.Context, code string, count bool) (string, error) {
	var destination string
	var err error
	if count {
		err = d.Pool.QueryRow(ctx, `
UPDATE monetization_suggestion_links
SET clicks = clicks + 1
WHERE code = $1
RETURNING destination`, code).Scan(&destination)
	} else {
		err = d.Pool.QueryRow(ctx, `SELECT destination FROM monetization_suggestion_links WHERE code=$1`, code).Scan(&destination)
	}
	if err != nil {
		return "", err
	}
	return destination, nil
}

// MonetizationLinkClicks is the stored click count for a code.
func (d *DB) MonetizationLinkClicks(ctx context.Context, code string) (int, error) {
	var n int
	err := d.Pool.QueryRow(ctx, `SELECT clicks FROM monetization_suggestion_links WHERE code=$1`, code).Scan(&n)
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, err
	}
	return n, err
}
